<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover,user-scalable=no"><title>KIN World</title>
<style>
:root{--bg:#0d0b1a;--fg:#fff;--card:#1a1530}
html,body{margin:0;height:100%;overflow:hidden;background:var(--bg);color:var(--fg);touch-action:none;user-select:none;-webkit-user-select:none;font-family:system-ui,sans-serif}
canvas{position:fixed;inset:0;width:100%;height:100%;display:block}
#cz{position:fixed;inset:0;z-index:1}
#jz{position:fixed;left:0;bottom:0;width:45%;height:65%;z-index:2}
#jb{position:fixed;left:max(30px,env(safe-area-inset-left));bottom:max(30px,env(safe-area-inset-bottom));width:120px;height:120px;border-radius:50%;border:2px solid #fff6;background:#fff1;z-index:2;pointer-events:none}
#jk{position:absolute;left:50%;top:50%;width:50px;height:50px;border-radius:50%;background:#fffa;transform:translate(-50%,-50%)}
#hud{position:fixed;top:max(8px,env(safe-area-inset-top));left:max(10px,env(safe-area-inset-left));z-index:3;pointer-events:none;font-weight:700;text-shadow:0 1px 3px #000}
#hb{width:170px;height:14px;background:#0008;border:2px solid #fff;border-radius:8px;overflow:hidden;margin:3px 0}
#hp{display:block;height:100%;background:linear-gradient(#ff5a5a,#c01818);width:100%}
#menu{position:fixed;top:max(8px,env(safe-area-inset-top));right:max(10px,env(safe-area-inset-right));z-index:4;font-size:20px;width:42px;height:42px;border-radius:50%;border:2px solid #fff8;background:#0006;color:#fff}
.b{position:fixed;z-index:4;border-radius:50%;border:3px solid #fff9;background:#0007;color:#fff;font-size:28px;touch-action:none;padding:0}
#atk{right:max(20px,env(safe-area-inset-right));bottom:max(22px,env(safe-area-inset-bottom));width:88px;height:88px}
#pow{right:calc(max(20px,env(safe-area-inset-right)) + 100px);bottom:max(36px,env(safe-area-inset-bottom));width:72px;height:72px;font-size:22px}
#jmp{right:calc(max(20px,env(safe-area-inset-right)) + 14px);bottom:calc(max(22px,env(safe-area-inset-bottom)) + 100px);width:68px;height:68px}
#msg{position:fixed;top:18%;left:0;right:0;text-align:center;z-index:3;font-size:22px;font-weight:800;text-shadow:0 2px 6px #000;opacity:0;transition:opacity .3s;pointer-events:none}
#fl{position:fixed;inset:0;z-index:3;box-shadow:inset 0 0 90px #f00;opacity:0;transition:opacity .3s;pointer-events:none}
#sel{position:fixed;inset:0;z-index:6;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;background:radial-gradient(#2e2158,var(--bg))}
#sel h1{margin:0;font-size:30px;letter-spacing:3px}#sel p{margin:0;opacity:.8}
.cards{display:flex;gap:12px;direction:ltr}
.card{width:30vw;max-width:170px;border:2px solid #555;border-radius:14px;padding:6px;text-align:center;background:var(--card);opacity:.7}
.card.on{border-color:var(--c);box-shadow:0 0 20px var(--c);opacity:1}
.card img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px;display:block}
.card b{display:block;margin-top:4px;color:var(--c)}.card small{opacity:.85}
#go{margin-top:6px;padding:10px 34px;font-size:20px;font-weight:800;border-radius:30px;border:0;background:#ffcf40;color:#222}
#rot{display:none;position:fixed;inset:0;z-index:9;background:var(--bg);align-items:center;justify-content:center;text-align:center;font-size:26px}
@media (orientation:portrait){#rot{display:flex}}
</style></head><body>
<div id="cz"></div><div id="jz"></div><div id="jb"><i id="jk"></i></div>
<div id="hud"><div id="nm"></div><div id="hb"><i id="hp"></i></div><div id="k"></div></div>
<button id="menu">☰</button>
<button id="atk" class="b">⚔️</button><button id="pow" class="b">✨</button><button id="jmp" class="b">⬆️</button>
<div id="msg"></div><div id="fl"></div>
<div id="sel"><h1>KIN WORLD</h1><p>اختار شخصيتك</p><div class="cards" id="cards"></div><button id="go">ابدأ اللعب ▶</button></div>
<div id="rot">📱<br>لف الموبايل أفقي</div>
